import React from 'react';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { ColumnListItem } from './ColumnListItem.js';
import { filterColumnsByString } from './filterColumnsByString.js';
import { NoItemsFound } from './NoItemsFound.js';
import { Divider } from '../../../typography/Divider.js';
import { ColumnMinInstance } from '../../types/internal-table-types.js';

// #region StyledComponents
const ColumnsListDivider = /* @__PURE__ */ styled(Divider)({
  marginTop: Spacings.Size0,
  marginBottom: Spacings.Size0,
});

// #region StyledComponents

type ColumnSettingsListProps = {
  columnCheckboxes?: React.ReactElement[];
  activeFilterValue: string;
  configuredColumns: ColumnMinInstance[];
  onColumnsReordering: React.Dispatch<React.SetStateAction<unknown[]>>;
  columnOrderSettings: boolean;
};

export const ColumnSettingsList = (props: ColumnSettingsListProps) => {
  const {
    activeFilterValue,
    columnCheckboxes,
    configuredColumns,
    onColumnsReordering,
    columnOrderSettings,
  } = props;
  if (!configuredColumns) {
    return null;
  }

  const filteredColumns = filterColumnsByString(
    configuredColumns as ColumnMinInstance[],
    activeFilterValue,
  );

  const visibilityIsConfigured = columnCheckboxes?.length !== 0;

  const renderColumns = () => {
    const columnsToRender: React.ReactElement[] = [];
    let extractedParentColumn: ColumnMinInstance;
    filteredColumns.forEach((column, index) => {
      let columnCheckbox: React.ReactElement | undefined;

      const isSubColumn = column.parent ? true : false;
      // If it is sub-column extract parent column from it
      if (column.parent) {
        // Extract parent column only once
        const parentColumnAlreadyExtracted =
          extractedParentColumn &&
          extractedParentColumn.id === column.parent.id;
        extractedParentColumn = column.parent;

        if (!parentColumnAlreadyExtracted) {
          for (const item in columnCheckboxes) {
            if (column.parent.id === columnCheckboxes[item].key) {
              columnCheckbox = columnCheckboxes[item];
            }
          }
          const listItem = (
            <React.Fragment key={`${column.parent.id}`}>
              {index !== 0 && <ColumnsListDivider />}
              <ColumnListItem
                column={extractedParentColumn}
                columnCheckbox={columnCheckbox}
                columnOrderSettings={!activeFilterValue && columnOrderSettings}
                configuredColumns={configuredColumns}
                onColumnsReordering={onColumnsReordering}
              />
            </React.Fragment>
          );
          columnsToRender.push(listItem);
        }
      }
      if (columnCheckboxes) {
        for (const item in columnCheckboxes) {
          if (column.id === columnCheckboxes[item].key) {
            columnCheckbox = columnCheckboxes[item];
          }
        }
      }
      const listItem = (
        <React.Fragment key={`${column.id}`}>
          {!isSubColumn && index !== 0 && <ColumnsListDivider />}
          <ColumnListItem
            column={column}
            columnCheckbox={columnCheckbox}
            columnOrderSettings={!activeFilterValue && columnOrderSettings}
            configuredColumns={configuredColumns}
            onColumnsReordering={onColumnsReordering}
          />
        </React.Fragment>
      );
      listItem && columnsToRender.push(listItem);
    });

    return columnsToRender;
  };

  if (
    filteredColumns.length === 0 ||
    (!visibilityIsConfigured && !columnOrderSettings)
  ) {
    return <NoItemsFound />;
  }

  return <>{renderColumns()}</>;
};
